{"version":3,"file":"exec-app.jsdbx","sources":["../../src/client/exec-app.tsx","../../src/client/exec-app.css"],"sourcesContent":["import React, { useState, useEffect } from 'react';
import NavHeader from './components/shared/NavHeader';
import './exec-app.css';

/*
 * Executive Dashboard — DarkOps
 * All KPI numbers are hardcoded to match spec exactly.
 * In production these would come from Table API calls.
 */

/* ─── Alert Banner ─── */
function AlertBanner() {
  return (
    <div className="exec-alert-banner">
      <div className="exec-alert-banner__left">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
          <path d="M12 2L1 21h22L12 2z" fill="none" stroke="#ef4444" strokeWidth="2" strokeLinejoin="round" />
          <path d="M12 9v4" stroke="#ef4444" strokeWidth="2" strokeLinecap="round" />
          <circle cx="12" cy="17" r="1" fill="#ef4444" />
        </svg>
        <span>Network health declining — backlog up 6.2%, 14 stores need intervention, 3 SLA breaches today.</span>
      </div>
      <span className="exec-alert-banner__label">AUTO-GENERATED SUMMARY</span>
    </div>
  );
}

/* ─── Page Header with Live Timer ─── */
function PageHeader() {
  const [seconds, setSeconds] = useState(17);

  useEffect(() => {
    const interval = setInterval(() => {
      setSeconds((s) => s + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="exec-page-header">
      <div className="exec-page-header__left">
        <h1 className="exec-page-header__title">Executive overview</h1>
        <p className="exec-page-header__subtitle">200 dark stores · 15 cities · 8,214 complaints in last 24h</p>
      </div>
      <div className="exec-page-header__right">
        <span className="exec-page-header__live-pill">
          <span className="exec-page-header__live-dot" />
          Updated {seconds}s ago · LIVE
        </span>
        <span className="exec-page-header__warn-pill">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
            <path d="M12 2L1 21h22L12 2z" fill="none" stroke="#ef4444" strokeWidth="2" strokeLinejoin="round" />
            <path d="M12 9v4" stroke="#ef4444" strokeWidth="2" strokeLinecap="round" />
            <circle cx="12" cy="17" r="1" fill="#ef4444" />
          </svg>
          14 stores need intervention · PulseScore &lt; 60
        </span>
      </div>
    </div>
  );
}

/* ─── PulseScore Ring Gauge (SVG) ─── */
function PulseScoreCard() {
  const score = 78;
  const radius = 44;
  const strokeWidth = 9;
  const circumference = 2 * Math.PI * radius;
  const progress = (score / 100) * circumference;

  return (
    <div className="exec-kpi-card exec-kpi-card--pulse">
      <span className="exec-kpi-card__label">NETWORK PULSESCORE</span>
      <div className="exec-kpi-card__ring">
        <svg width="120" height="120" viewBox="0 0 120 120">
          <circle
            cx="60" cy="60" r={radius}
            fill="none"
            stroke="#1a2035"
            strokeWidth={strokeWidth}
          />
          <circle
            cx="60" cy="60" r={radius}
            fill="none"
            stroke="#f59e0b"
            strokeWidth={strokeWidth}
            strokeDasharray={`${progress} ${circumference}`}
            strokeLinecap="round"
            transform="rotate(-90 60 60)"
          />
          <text x="60" y="56" textAnchor="middle" className="exec-kpi-card__ring-score">78</text>
          <text x="60" y="74" textAnchor="middle" className="exec-kpi-card__ring-sub">/100</text>
        </svg>
      </div>
      <p className="exec-kpi-card__caption">
        <span className="exec-kpi-card__caption-trend exec-kpi-card__caption-trend--amber">&#x2193;3% pts vs prior 30d</span> · headline metric
      </p>
    </div>
  );
}

/* ─── KPI Card ─── */
interface KpiProps {
  label: string;
  value: string;
  valueClass?: string;
  caption: string;
}

function KpiCard({ label, value, valueClass, caption }: KpiProps) {
  return (
    <div className="exec-kpi-card">
      <span className="exec-kpi-card__label">{label}</span>
      <span className={`exec-kpi-card__value ${valueClass || ''}`}>{value}</span>
      <p className="exec-kpi-card__caption" dangerouslySetInnerHTML={{ __html: caption }} />
    </div>
  );
}

/* ─── KPI Row ─── */
function KpiRow() {
  return (
    <div className="exec-kpi-row">
      <PulseScoreCard />
      <KpiCard
        label="OPEN COMPLAINTS"
        value="8,214"
        caption='<span class="exec-kpi-card__caption-trend exec-kpi-card__caption-trend--red">&#x2197;6.2% vs prior 30d</span>'
      />
      <KpiCard
        label="SLA COMPLIANCE"
        value="91.4 %"
        caption='<span class="exec-kpi-card__caption-trend exec-kpi-card__caption-trend--red">&#x2193;1.8% target 95%</span>'
      />
      <KpiCard
        label="AVG RESOLUTION TIME"
        value="94m"
        caption='<span class="exec-kpi-card__caption-trend exec-kpi-card__caption-trend--red">&#x2193;7% target 90m</span>'
      />
      <KpiCard
        label="REFUND RATE"
        value="4.6 % of orders"
        caption='<span class="exec-kpi-card__caption-trend exec-kpi-card__caption-trend--red">&#x2197;0.7% target 4.0%</span>'
      />
      <KpiCard
        label="CRITICAL STORES"
        value="14 of 200"
        valueClass="exec-kpi-card__value--red"
        caption='<span class="exec-kpi-card__caption-trend exec-kpi-card__caption-trend--red">&#x2197;3% PulseScore &lt; 60, no active fix</span>'
      />
    </div>
  );
}

/* ─── Complaint Volume Line Chart (SVG) ─── */
function ComplaintChart() {
  const width = 600;
  const height = 260;
  const pad = { top: 24, right: 20, bottom: 44, left: 52 };
  const cw = width - pad.left - pad.right;
  const ch = height - pad.top - pad.bottom;

  const xLabels = ['02 Jul', '07 Jul', '12 Jul', '17 Jul', '22 Jul', '27 Jul'];
  const yMax = 10000;
  const yTicks = [0, 2500, 5000, 7500, 10000];

  // Blue line: complaints raised (above green, widening gap after 21 Jul)
  const raised = [3400, 4600, 5400, 6400, 8200, 9600];
  // Green line: complaints resolved
  const resolved = [3200, 4200, 4800, 5200, 5900, 6400];

  const toX = (i: number) => pad.left + (i / (xLabels.length - 1)) * cw;
  const toY = (v: number) => pad.top + ch - (v / yMax) * ch;

  const linePath = (data: number[]) =>
    'M' + data.map((v, i) => `${toX(i)},${toY(v)}`).join(' L');

  const areaPath = (data: number[]) => {
    const line = data.map((v, i) => `${toX(i)},${toY(v)}`).join(' L');
    return `M${line} L${toX(data.length - 1)},${toY(0)} L${toX(0)},${toY(0)} Z`;
  };

  return (
    <div className="exec-card exec-card--wide">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Complaint volume vs resolved — 30 days</h3>
          <p className="exec-card__subtitle">Intake is outpacing resolution since 21 Jul; backlog is accumulating.</p>
        </div>
        <span className="exec-card__badge exec-card__badge--red">Backlog +1,140</span>
      </div>
      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="exec-chart-svg">
        {yTicks.map((tick) => (
          <g key={tick}>
            <line x1={pad.left} y1={toY(tick)} x2={width - pad.right} y2={toY(tick)} stroke="#1a2035" strokeWidth="1" />
            <text x={pad.left - 8} y={toY(tick) + 4} textAnchor="end" className="exec-chart__axis-text">
              {tick === 0 ? '0' : `${(tick / 1000).toFixed(1)}k`}
            </text>
          </g>
        ))}
        {xLabels.map((label, i) => (
          <text key={label} x={toX(i)} y={height - 10} textAnchor="middle" className="exec-chart__axis-text">
            {label}
          </text>
        ))}
        <path d={areaPath(raised)} fill="rgba(59, 130, 246, 0.1)" />
        <path d={linePath(raised)} fill="none" stroke="#3b82f6" strokeWidth="2" />
        <path d={areaPath(resolved)} fill="rgba(34, 197, 94, 0.08)" />
        <path d={linePath(resolved)} fill="none" stroke="#22c55e" strokeWidth="2" />
      </svg>
      <div className="exec-chart__legend">
        <span className="exec-chart__legend-item">
          <span className="exec-chart__legend-dot exec-chart__legend-dot--blue" />
          Complaints raised
        </span>
        <span className="exec-chart__legend-item">
          <span className="exec-chart__legend-dot exec-chart__legend-dot--green" />
          Complaints resolved
        </span>
      </div>
    </div>
  );
}

/* ─── Red Alerts ─── */
const ALERTS = [
  {
    id: 'ALT-40219',
    title: 'Store DS-1462 PulseScore dropped',
    desc: 'Kolkata Central DS · PulseScore 31 · freezer FRZ-08 down, 41 complaints past SLA',
    time: '18m ago',
    store: 'DS-1462',
  },
  {
    id: 'ALT-40217',
    title: 'Cold chain failure',
    desc: 'Mumbai Industrial Belt DS · Freezer FRZ-08 offline 3h',
    time: '52m ago',
    store: 'DS-2162',
  },
  {
    id: 'ALT-40214',
    title: 'Refund rate spike',
    desc: 'Bengaluru Ring Road DS · Refunds 11.2% vs 4.6% target',
    time: '1h 20m ago',
    store: 'DS-1525',
  },
  {
    id: 'ALT-40208',
    title: 'Picker capacity shortfall',
    desc: 'Kochi Airport Road DS · 6 of 14 pickers on shift',
    time: '2h ago',
    store: 'DS-1714',
  },
  {
    id: 'ALT-40203',
    title: 'Repeat missing-item claims',
    desc: 'Hyderabad Old City DS · 23 claims from 9 customers',
    time: '3h 10m ago',
    store: 'DS-1756',
  },
];

function RedAlerts() {
  const navigate = (store: string) => {
    window.location.href = `/x_2145749_qc_dark_store_dashboard.do?store=${store}`;
  };

  return (
    <div className="exec-card exec-card--narrow">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Red alerts</h3>
          <p className="exec-card__subtitle">Needs a leadership decision in the next 4 hours.</p>
        </div>
      </div>
      <div className="exec-alerts-list">
        {ALERTS.map((alert) => (
          <div
            className="exec-alert-row"
            key={alert.id}
            onClick={() => navigate(alert.store)}
          >
            <span className="exec-alert-row__dot" />
            <div className="exec-alert-row__body">
              <div className="exec-alert-row__top">
                <span className="exec-alert-row__title">{alert.title}</span>
                <span className="exec-alert-row__id">{alert.id}</span>
              </div>
              <p className="exec-alert-row__desc">{alert.desc}</p>
              <span className="exec-alert-row__time">{alert.time}</span>
            </div>
            <span className="exec-alert-row__chevron">&gt;</span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ─── City Bar Chart (CSS) ─── */
const CITY_DATA = [
  { city: 'Mumbai', value: 6200 },
  { city: 'Kolkata', value: 5600 },
  { city: 'Indore', value: 5000 },
  { city: 'Hyderabad', value: 4600 },
  { city: 'Nagpur', value: 4100 },
  { city: 'Surat', value: 3700 },
  { city: 'Jaipur', value: 3400 },
  { city: 'Bengaluru', value: 3100 },
  { city: 'Chandigarh', value: 2900 },
  { city: 'Delhi NCR', value: 2600 },
];

function CityChart() {
  const yMax = 8000;
  const yTicks = [0, 2000, 4000, 6000, 8000];

  return (
    <div className="exec-card exec-card--wide">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">City-wise complaints &amp; SLA</h3>
          <p className="exec-card__subtitle">Where to send regional ops leadership this week.</p>
        </div>
      </div>
      <div className="exec-bar-chart">
        <div className="exec-bar-chart__y-axis">
          {yTicks.slice().reverse().map((t) => (
            <span key={t} className="exec-bar-chart__y-label">{t === 0 ? '0' : `${t / 1000}k`}</span>
          ))}
        </div>
        <div className="exec-bar-chart__bars">
          {CITY_DATA.map((item) => (
            <div className="exec-bar-chart__col" key={item.city}>
              <div className="exec-bar-chart__bar-wrap">
                <div
                  className="exec-bar-chart__bar"
                  style={{ height: `${(item.value / yMax) * 100}%` }}
                />
              </div>
              <span className="exec-bar-chart__x-label">{item.city}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ─── Top 5 Worst Stores ─── */
const WORST_STORES = [
  { name: 'Kolkata Central DS', id: 'DS-1462', city: 'Kolkata', sla: '61.9%', refunds: '10%', score: 31, change: 8 },
  { name: 'Mumbai Industrial Belt DS', id: 'DS-2162', city: 'Mumbai', sla: '57.3%', refunds: '9.6%', score: 31, change: 6 },
  { name: 'Bengaluru Ring Road DS', id: 'DS-1525', city: 'Bengaluru', sla: '60.6%', refunds: '9.2%', score: 32, change: 8 },
  { name: 'Kochi Airport Road DS', id: 'DS-1714', city: 'Kochi', sla: '61.4%', refunds: '10.1%', score: 32, change: 8 },
  { name: 'Hyderabad Old City DS', id: 'DS-1756', city: 'Hyderabad', sla: '64%', refunds: '9.5%', score: 32, change: 5 },
];

function TopWorstStores() {
  const navigate = (id: string) => {
    window.location.href = `/x_2145749_qc_dark_store_dashboard.do?store=${id}`;
  };

  return (
    <div className="exec-card exec-card--narrow">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Top 5 worst stores</h3>
          <p className="exec-card__subtitle">Lowest PulseScore — click to open the store's dashboard.</p>
        </div>
      </div>
      <div className="exec-stores-list">
        {WORST_STORES.map((store) => (
          <div
            className="exec-store-row"
            key={store.id}
            onClick={() => navigate(store.id)}
          >
            <div className="exec-store-row__body">
              <span className="exec-store-row__name">{store.name}</span>
              <span className="exec-store-row__info">
                {store.id} · {store.city} · SLA {store.sla} · refunds {store.refunds}
              </span>
            </div>
            <div className="exec-store-row__score-block">
              <span className="exec-store-row__score">{store.score}</span>
              <span className="exec-store-row__trend">&#x2193;{store.change} this week</span>
            </div>
            <span className="exec-store-row__chevron">&gt;</span>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ─── Store Health Heatmap ─── */
interface HeatmapCity {
  name: string;
  stores: { color: string; id: string }[];
}

function buildStores(count: number, redPct: number, amberPct: number, prefix: string): { color: string; id: string }[] {
  const stores: { color: string; id: string }[] = [];
  const pattern = [0.12, 0.87, 0.55, 0.93, 0.28, 0.71, 0.14, 0.82, 0.44, 0.96, 0.19, 0.77, 0.62, 0.09, 0.65, 0.35, 0.90, 0.40, 0.75, 0.06, 0.50, 0.83];
  for (let i = 0; i < count; i++) {
    const v = pattern[i % pattern.length];
    let color: string;
    if (v < redPct) color = '#ef4444';
    else if (v < redPct + amberPct) color = '#f59e0b';
    else color = '#22c55e';
    stores.push({ color, id: `${prefix}-${1000 + i}` });
  }
  return stores;
}

const HEATMAP_LEFT: HeatmapCity[] = [
  { name: 'Bengaluru', stores: buildStores(18, 0.10, 0.25, 'DS') },
  { name: 'Delhi NCR', stores: buildStores(20, 0.08, 0.20, 'DS') },
  { name: 'Pune', stores: buildStores(15, 0.05, 0.20, 'DS') },
  { name: 'Kolkata', stores: buildStores(16, 0.15, 0.30, 'DS') },
  { name: 'Jaipur', stores: buildStores(12, 0.08, 0.25, 'DS') },
  { name: 'Chandigarh', stores: buildStores(10, 0.05, 0.20, 'DS') },
  { name: 'Kochi', stores: buildStores(11, 0.12, 0.25, 'DS') },
  { name: 'Nagpur', stores: buildStores(9, 0.10, 0.30, 'DS') },
];

const HEATMAP_RIGHT: HeatmapCity[] = [
  { name: 'Mumbai', stores: buildStores(22, 0.12, 0.25, 'DS') },
  { name: 'Hyderabad', stores: buildStores(17, 0.10, 0.28, 'DS') },
  { name: 'Chennai', stores: buildStores(14, 0.06, 0.20, 'DS') },
  { name: 'Ahmedabad', stores: buildStores(13, 0.05, 0.15, 'DS') },
  { name: 'Lucknow', stores: buildStores(11, 0.08, 0.22, 'DS') },
  { name: 'Indore', stores: buildStores(10, 0.10, 0.30, 'DS') },
  { name: 'Surat', stores: buildStores(9, 0.07, 0.20, 'DS') },
];

function StoreHeatmap() {
  const navigateStore = (id: string) => {
    window.location.href = `/x_2145749_qc_dark_store_dashboard.do?store=${id}`;
  };

  const renderColumn = (cities: HeatmapCity[]) => (
    <div className="exec-heatmap__col">
      {cities.map((city) => (
        <div className="exec-heatmap__row" key={city.name}>
          <span className="exec-heatmap__city">{city.name}</span>
          <div className="exec-heatmap__cells">
            {city.stores.map((s, i) => (
              <div
                key={i}
                className="exec-heatmap__cell"
                style={{ background: s.color }}
                onClick={() => navigateStore(s.id)}
                title={s.id}
              />
            ))}
          </div>
        </div>
      ))}
    </div>
  );

  return (
    <div className="exec-card exec-card--full">
      <div className="exec-card__header">
        <div>
          <h3 className="exec-card__title">Store health heatmap</h3>
          <p className="exec-card__subtitle">Each cell is one dark store, coloured by PulseScore. Click any cell to drill in.</p>
        </div>
        <div className="exec-heatmap__legend">
          <span className="exec-heatmap__legend-item">
            <span className="exec-heatmap__swatch" style={{ background: '#22c55e' }} />
            &gt;= 80
          </span>
          <span className="exec-heatmap__legend-item">
            <span className="exec-heatmap__swatch" style={{ background: '#f59e0b' }} />
            60–79
          </span>
          <span className="exec-heatmap__legend-item">
            <span className="exec-heatmap__swatch" style={{ background: '#ef4444' }} />
            &lt; 60
          </span>
        </div>
      </div>
      <div className="exec-heatmap__grid">
        {renderColumn(HEATMAP_LEFT)}
        {renderColumn(HEATMAP_RIGHT)}
      </div>
    </div>
  );
}

/* ─── Main Executive Dashboard ─── */
function ExecApp() {
  return (
    <div className="exec-dashboard">
      <NavHeader />
      <AlertBanner />
      <div className="exec-dashboard__content">
        <PageHeader />
        <KpiRow />
        <div className="exec-dashboard__two-col">
          <ComplaintChart />
          <RedAlerts />
        </div>
        <div className="exec-dashboard__two-col">
          <CityChart />
          <TopWorstStores />
        </div>
        <StoreHeatmap />
      </div>
    </div>
  );
}

export default ExecApp;
","/* ─── Executive Dashboard — Dark Theme ─── */

/* ─── Dashboard Shell ─── */
.exec-dashboard {
  min-height: 100vh;
  background: #0a0e14;
  color: #e2e8f0;
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif;
}

.exec-dashboard__content {
  padding: 24px;
  max-width: 1440px;
  margin: 0 auto;
}

/* ─── Alert Banner ─── */
.exec-alert-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 24px;
  background: rgba(239, 68, 68, 0.06);
  border-left: 3px solid #ef4444;
}

.exec-alert-banner__left {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 13px;
  color: #fca5a5;
}

.exec-alert-banner__label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #64748b;
  text-transform: uppercase;
}

/* ─── Page Header ─── */
.exec-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 24px;
}

.exec-page-header__title {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 4px 0;
  color: #e2e8f0;
}

.exec-page-header__subtitle {
  font-size: 14px;
  color: #64748b;
  margin: 0;
}

.exec-page-header__right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.exec-page-header__live-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #94a3b8;
  background: rgba(34, 197, 94, 0.06);
  border: 1px solid rgba(34, 197, 94, 0.2);
  border-radius: 20px;
  padding: 5px 14px;
}

.exec-page-header__live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  animation: pulse-glow 2s infinite;
}

@keyframes pulse-glow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

.exec-page-header__warn-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: #fca5a5;
  background: rgba(239, 68, 68, 0.06);
  border: 1px solid rgba(239, 68, 68, 0.2);
  border-radius: 20px;
  padding: 5px 14px;
}

/* ─── KPI Row ─── */
.exec-kpi-row {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr 1fr 1fr 1fr;
  gap: 16px;
  margin-bottom: 24px;
}

/* ─── KPI Card ─── */
.exec-kpi-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.exec-kpi-card--pulse {
  align-items: center;
  justify-content: center;
  padding: 24px 20px;
}

.exec-kpi-card__label {
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  margin-bottom: 12px;
}

.exec-kpi-card__ring {
  margin: 4px 0 12px;
}

.exec-kpi-card__ring-score {
  font-size: 28px;
  font-weight: 700;
  fill: #e2e8f0;
  font-variant-numeric: tabular-nums;
}

.exec-kpi-card__ring-sub {
  font-size: 12px;
  fill: #64748b;
}

.exec-kpi-card__value {
  font-size: 28px;
  font-weight: 700;
  color: #e2e8f0;
  font-variant-numeric: tabular-nums;
  margin-bottom: auto;
  padding-bottom: 12px;
}

.exec-kpi-card__value--red {
  color: #ef4444;
}

.exec-kpi-card__caption {
  font-size: 11px;
  color: #64748b;
  margin: 0;
  line-height: 1.5;
}

.exec-kpi-card__caption-trend--red {
  color: #ef4444;
  font-weight: 600;
}

.exec-kpi-card__caption-trend--amber {
  color: #f59e0b;
  font-weight: 600;
}

.exec-kpi-card__caption-trend--green {
  color: #22c55e;
  font-weight: 600;
}

/* ─── Two-Column Layout ─── */
.exec-dashboard__two-col {
  display: grid;
  grid-template-columns: 65fr 35fr;
  gap: 16px;
  margin-bottom: 24px;
}

/* ─── Generic Card ─── */
.exec-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 24px;
}

.exec-card--full {
  margin-bottom: 24px;
}

.exec-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}

.exec-card__title {
  font-size: 15px;
  font-weight: 600;
  color: #e2e8f0;
  margin: 0 0 4px 0;
}

.exec-card__subtitle {
  font-size: 12px;
  color: #64748b;
  margin: 0;
}

.exec-card__badge {
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
  flex-shrink: 0;
  white-space: nowrap;
}

.exec-card__badge--red {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.08);
  border: 1px solid rgba(239, 68, 68, 0.2);
}

/* ─── SVG Line Chart ─── */
.exec-chart-svg {
  display: block;
  width: 100%;
}

.exec-chart__axis-text {
  font-size: 10px;
  fill: #475569;
}

.exec-chart__legend {
  display: flex;
  gap: 20px;
  margin-top: 14px;
}

.exec-chart__legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #64748b;
}

.exec-chart__legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.exec-chart__legend-dot--blue {
  background: #3b82f6;
}

.exec-chart__legend-dot--green {
  background: #22c55e;
}

/* ─── Red Alerts List ─── */
.exec-alerts-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.exec-alert-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.12s ease;
}

.exec-alert-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.exec-alert-row__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #ef4444;
  flex-shrink: 0;
  margin-top: 5px;
}

.exec-alert-row__body {
  flex: 1;
  min-width: 0;
}

.exec-alert-row__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.exec-alert-row__title {
  font-size: 13px;
  font-weight: 600;
  color: #e2e8f0;
}

.exec-alert-row__id {
  font-size: 10px;
  font-family: 'SF Mono', 'Fira Code', monospace;
  color: #64748b;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid #1a2035;
  border-radius: 4px;
  padding: 1px 6px;
  white-space: nowrap;
}

.exec-alert-row__desc {
  font-size: 11px;
  color: #64748b;
  margin: 0 0 2px 0;
  line-height: 1.4;
}

.exec-alert-row__time {
  font-size: 10px;
  color: #475569;
}

.exec-alert-row__chevron {
  color: #475569;
  font-size: 14px;
  flex-shrink: 0;
  margin-top: 2px;
}

/* ─── City Bar Chart ─── */
.exec-bar-chart {
  display: flex;
  gap: 8px;
  height: 200px;
}

.exec-bar-chart__y-axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 0 4px 24px 0;
}

.exec-bar-chart__y-label {
  font-size: 10px;
  color: #475569;
  text-align: right;
  width: 28px;
}

.exec-bar-chart__bars {
  display: flex;
  flex: 1;
  align-items: flex-end;
  gap: 6px;
  padding-bottom: 24px;
  border-bottom: 1px solid #1a2035;
}

.exec-bar-chart__col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}

.exec-bar-chart__bar-wrap {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.exec-bar-chart__bar {
  width: 65%;
  background: #3b82f6;
  border-radius: 3px 3px 0 0;
  min-height: 4px;
  transition: background 0.12s ease;
}

.exec-bar-chart__bar:hover {
  background: #60a5fa;
}

.exec-bar-chart__x-label {
  font-size: 9px;
  color: #475569;
  margin-top: 8px;
  text-align: center;
  white-space: nowrap;
}

/* ─── Worst Stores List ─── */
.exec-stores-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.exec-store-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.12s ease;
}

.exec-store-row:hover {
  background: rgba(255, 255, 255, 0.03);
}

.exec-store-row__body {
  flex: 1;
  min-width: 0;
}

.exec-store-row__name {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: #e2e8f0;
  margin-bottom: 2px;
}

.exec-store-row__info {
  font-size: 11px;
  color: #64748b;
}

.exec-store-row__score-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  flex-shrink: 0;
}

.exec-store-row__score {
  font-size: 22px;
  font-weight: 700;
  color: #ef4444;
  font-variant-numeric: tabular-nums;
}

.exec-store-row__trend {
  font-size: 10px;
  color: #ef4444;
}

.exec-store-row__chevron {
  color: #475569;
  font-size: 14px;
  flex-shrink: 0;
}

/* ─── Heatmap ─── */
.exec-heatmap__legend {
  display: flex;
  gap: 16px;
  align-items: center;
}

.exec-heatmap__legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #64748b;
}

.exec-heatmap__swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  display: inline-block;
}

.exec-heatmap__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.exec-heatmap__col {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.exec-heatmap__row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.exec-heatmap__city {
  font-size: 12px;
  color: #64748b;
  width: 90px;
  flex-shrink: 0;
  text-align: right;
}

.exec-heatmap__cells {
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
}

.exec-heatmap__cell {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

.exec-heatmap__cell:hover {
  transform: scale(1.5);
  box-shadow: 0 0 6px rgba(255, 255, 255, 0.15);
}

/* ─── Responsive ─── */
@media (max-width: 1200px) {
  .exec-kpi-row {
    grid-template-columns: repeat(3, 1fr);
  }
  .exec-dashboard__two-col {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .exec-kpi-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .exec-heatmap__grid {
    grid-template-columns: 1fr;
  }
  .exec-page-header {
    flex-direction: column;
    gap: 12px;
  }
}
